<?php namespace App\Domains\Comercial\LiveSales\Actions; use App\Domains\Auditoria\DTOs\RegistrarAuditoriaData; use App\Domains\Auditoria\Services\RegistrarAuditoriaService; use App\Models\SesionLive; class CrearSesionLiveAction{ public function __construct(private RegistrarAuditoriaService $auditoriaService){} public function execute(array $data):SesionLive{ $sesion = SesionLive::create($data); $contexto = RegistrarAuditoriaData::fromRequest(request()); $this->auditoriaService->registrarInsercion($contexto, 'LiveSales', 'sesiones_live', (string) $sesion->cod_sesion_live); return $sesion; } }
